{
  "description": "Configuration to Login via Serial, set VendorDtbOverlays and reboot",
  "attempts": 1,
  "retryFromLastFailedGroup": false,
  "groups": [
    {
      "name": "Serial Login and Configure",
      "attempts": 1,
      "steps": [
        {
          "step": "sleep",
          "description": "Wait for device to boot",
          "input": [
            {
              "sleepTimeInSec": 120
            }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Wake up console",
          "input": [
            {
              "command": "\n",
              "portIndex": 0,
              "appendNewLine": true,
              "raiseErrorOnFailure": false
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for login prompt",
          "input": [
            {
              "sleepTimeInSec": 5
            }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Send Username",
          "input": [
            {
              "command": "root",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for password prompt",
          "input": [
            {
              "sleepTimeInSec": 2
            }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Send Password",
          "input": [
            {
              "command": "oelinux123",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for shell",
          "input": [
            {
              "sleepTimeInSec": 5
            }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Execute Configuration Commands",
          "input": [
            {
              "command": "echo -n \"camx\" > /var/data",
              "portIndex": 0,
              "appendNewLine": true
            },
            {
              "command": "efivar -n 882f8c2b-9646-435f-8de5-f208ff80c1bd-VendorDtbOverlays -w -f /var/data",
              "portIndex": 0,
              "appendNewLine": true
            },
            {
              "command": "efivar -n 882f8c2b-9646-435f-8de5-f208ff80c1bd-VendorDtbOverlays -p",
              "portIndex": 0,
              "appendNewLine": true
            },
            {
              "command": "sync",
              "portIndex": 0,
              "appendNewLine": true
            },
            {
              "command": "nmcli dev wifi connect Hydra password K5x48Vz3",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Ensure sync completes",
          "input": [
            {
              "sleepTimeInSec": 5
            }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "check ip addr",
          "input": [
            {
              "command": "ip addr",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Reboot Device",
          "input": [
            {
              "command": "reboot",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        }
      ]
    }
  ]
}
